import java.util.PriorityQueue;

/**
 * Computes a Minimum Spanning Tree (MST) — or, for a disconnected graph, a Minimum
 * Spanning Forest (MSF) — of an undirected, weighted graph using Prim's algorithm.
 *
 * <p>{@link #compute(Graph)} returns the MST of a connected graph and rejects a
 * disconnected one. {@link #computeForest(Graph)} is the general case: it grows one
 * minimum spanning tree per connected component and returns the collection, so it works
 * for any graph (isolated vertices become single-vertex, zero-edge components).
 *
 * <p>The algorithm operates on an adjacency-list {@link Graph}, so edge enumeration is
 * proportional to the number of edges rather than to {@code V^2}. Combined with a binary
 * heap to select the next cheapest crossing edge, the running time is {@code O(E log V)},
 * which is efficient for sparse graphs. A convenience adapter,
 * {@link Graph#fromAdjacencyMatrix(int[][])}, accepts the classic matrix form.
 */
public final class PrimsMst {

    private PrimsMst() {
        // Utility class: no instances.
    }

    /**
     * An edge of the minimum spanning tree, connecting {@code from} to {@code to}
     * with the given {@code weight}.
     */
    record Edge(int from, int to, int weight) {}

    /**
     * The result of a single-tree MST computation: the chosen edges and their total
     * weight. For a single-vertex component this holds no edges and zero weight.
     */
    record MstResult(List<Edge> edges, long totalWeight) {
        MstResult {
            edges = List.copyOf(edges);
        }
    }

    /**
     * The result of a Minimum Spanning Forest computation: one {@link MstResult} per
     * connected component, in ascending order of each component's lowest vertex index.
     */
    record MsfResult(List<MstResult> components) {
        MsfResult {
            components = List.copyOf(components);
        }

        /** The number of connected components (trees) in the forest. */
        int componentCount() {
            return components.size();
        }

        /** Every edge across all component trees. */
        List<Edge> edges() {
            return components.stream().flatMap(component -> component.edges().stream()).toList();
        }

        /** The combined weight of all component trees. */
        long totalWeight() {
            return components.stream().mapToLong(MstResult::totalWeight).sum();
        }
    }

    /**
     * A pluggable source of graph data for the MST/MSF algorithm. An implementation reports
     * how many vertices the graph has and feeds each of its edges to a sink; the framework
     * ({@link Graph#from(GraphBuilder)}, {@link #compute(GraphBuilder)},
     * {@link #computeForest(GraphBuilder)}) assembles and validates the {@link Graph}.
     *
     * <p>Implement this to load a graph from any origin — a file, a database, a network
     * service, or one generated on the fly — without depending on a particular text format
     * or on {@code Graph}'s internals. {@link EdgeListGraphBuilder} is the built-in
     * implementation for the edge-list text format.
     */
    public interface GraphBuilder {

        /** The number of vertices in the graph; vertices are indexed {@code 0..count-1}. */
        int vertexCount();

        /** Feeds every undirected edge of the graph to {@code sink} exactly once. */
        void provideEdges(EdgeSink sink);

        /** Receives an undirected edge with a positive weight. */
        @FunctionalInterface
        interface EdgeSink {
            void accept(int from, int to, int weight);
        }
    }

    /**
     * An undirected, weighted graph stored as adjacency lists. Edges are added in both
     * directions; weights must be positive.
     */
    static final class Graph {

        /** Sentinel weight indicating "no edge" in an adjacency matrix. */
        private static final int NO_EDGE = 0;

        /** A weighted link to a neighbouring vertex. */
        private record Neighbor(int vertex, int weight) {}

        private final List<List<Neighbor>> adjacency;

        Graph(int vertexCount) {
            if (vertexCount < 0) {
                throw new IllegalArgumentException("Vertex count must not be negative: " + vertexCount);
            }
            adjacency = new ArrayList<>(vertexCount);
            for (int i = 0; i < vertexCount; i++) {
                adjacency.add(new ArrayList<>());
            }
        }

        int vertexCount() {
            return adjacency.size();
        }

        /** Adds an undirected edge between {@code u} and {@code v} with positive {@code weight}. */
        void addEdge(int u, int v, int weight) {
            checkVertex(u);
            checkVertex(v);
            if (weight <= 0) {
                throw new IllegalArgumentException("Edge weight must be positive: " + weight);
            }
            adjacency.get(u).add(new Neighbor(v, weight));
            adjacency.get(v).add(new Neighbor(u, weight));
        }

        private List<Neighbor> neighbors(int vertex) {
            return adjacency.get(vertex);
        }

        private void checkVertex(int vertex) {
            if (vertex < 0 || vertex >= adjacency.size()) {
                throw new IndexOutOfBoundsException("Vertex out of range: " + vertex);
            }
        }

        /**
         * Builds a {@code Graph} from a square, symmetric adjacency matrix where
         * {@code matrix[u][v] == 0} denotes the absence of an edge. Only the upper
         * triangle is read, so the edge is added exactly once.
         */
        static Graph fromAdjacencyMatrix(int[][] matrix) {
            if (matrix == null) {
                throw new IllegalArgumentException("Adjacency matrix must not be null.");
            }
            for (int[] row : matrix) {
                if (row == null || row.length != matrix.length) {
                    throw new IllegalArgumentException("Adjacency matrix must be square.");
                }
            }
            Graph graph = new Graph(matrix.length);
            for (int u = 0; u < matrix.length; u++) {
                for (int v = u + 1; v < matrix.length; v++) {
                    if (matrix[u][v] != NO_EDGE) {
                        graph.addEdge(u, v, matrix[u][v]);
                    }
                }
            }
            return graph;
        }

        /**
         * Reads a graph from an edge-list file. See {@link #fromEdgeList(Iterable)} for the
         * accepted format.
         *
         * @throws IOException if the file cannot be read
         * @throws IllegalArgumentException if {@code path} is null or the content is malformed
         */
        static Graph fromEdgeListFile(Path path) throws IOException {
            if (path == null) {
                throw new IllegalArgumentException("Path must not be null.");
            }
            return fromEdgeList(Files.readAllLines(path));
        }

        /**
         * Builds a graph from an edge list given as a sequence of text lines.
         *
         * <p>The format is line-oriented:
         * <ul>
         *   <li>{@code from to weight} — an undirected edge between two vertex indices with a
         *       positive integer weight (tokens separated by any whitespace).</li>
         *   <li>{@code vertices N} — an optional directive fixing the vertex count to {@code N},
         *       which is how isolated vertices (those in no edge) are represented. It must be at
         *       least one greater than the largest vertex index referenced.</li>
         *   <li>A {@code #} starts a comment that runs to the end of the line; blank lines are
         *       ignored.</li>
         * </ul>
         * When no {@code vertices} directive is given, the vertex count is inferred as the
         * largest referenced index plus one.
         *
         * @throws IllegalArgumentException if {@code lines} is null or any line is malformed
         *                                  (with the offending line number in the message)
         */
        static Graph fromEdgeList(Iterable<String> lines) {
            if (lines == null) {
                throw new IllegalArgumentException("Edge list must not be null.");
            }
            List<int[]> edges = new ArrayList<>();
            int maxVertex = -1;
            int declaredCount = -1;
            int lineNumber = 0;
            for (String rawLine : lines) {
                lineNumber++;
                String line = stripComment(rawLine).strip();
                if (line.isEmpty()) {
                    continue;
                }
                String[] tokens = line.split("\\s+");
                if (tokens[0].equalsIgnoreCase("vertices")) {
                    if (tokens.length != 2) {
                        throw malformed(lineNumber, "expected 'vertices <count>'");
                    }
                    declaredCount = parseIndex(tokens[1], lineNumber, "vertex count");
                    continue;
                }
                if (tokens.length != 3) {
                    throw malformed(lineNumber, "expected 'from to weight'");
                }
                int from = parseIndex(tokens[0], lineNumber, "vertex");
                int to = parseIndex(tokens[1], lineNumber, "vertex");
                int weight = parseIndex(tokens[2], lineNumber, "weight");
                if (weight <= 0) {
                    throw malformed(lineNumber, "weight must be positive: " + weight);
                }
                edges.add(new int[] {from, to, weight});
                maxVertex = Math.max(maxVertex, Math.max(from, to));
            }

            int vertexCount = maxVertex + 1;
            if (declaredCount >= 0) {
                if (declaredCount < vertexCount) {
                    throw new IllegalArgumentException("Declared vertex count " + declaredCount
                        + " is smaller than the highest referenced vertex index " + maxVertex + ".");
                }
                vertexCount = declaredCount;
            }

            Graph graph = new Graph(vertexCount);
            for (int[] edge : edges) {
                graph.addEdge(edge[0], edge[1], edge[2]);
            }
            return graph;
        }

        /** Returns {@code line} with any {@code #}-comment removed. */
        private static String stripComment(String line) {
            int hash = line.indexOf('#');
            return hash < 0 ? line : line.substring(0, hash);
        }

        private static int parseIndex(String token, int lineNumber, String what) {
            try {
                int value = Integer.parseInt(token);
                if (value < 0) {
                    throw malformed(lineNumber, what + " must not be negative: " + token);
                }
                return value;
            } catch (NumberFormatException e) {
                throw malformed(lineNumber, "invalid " + what + ": '" + token + "'");
            }
        }

        private static IllegalArgumentException malformed(int lineNumber, String detail) {
            return new IllegalArgumentException("Edge list line " + lineNumber + ": " + detail);
        }
    }

    /**
     * Computes the minimum spanning tree of a connected {@code graph}.
     *
     * @param graph an undirected, weighted, connected graph
     * @return the MST edges (in the order vertices are added) and their total weight
     * @throws IllegalArgumentException if {@code graph} is null or not connected
     * @see #computeForest(Graph) for graphs that may be disconnected
     */
    static MstResult compute(Graph graph) {
        MsfResult forest = computeForest(graph);
        if (forest.componentCount() > 1) {
            throw new IllegalArgumentException(
                "Graph is not connected; no spanning tree exists. Use computeForest for a minimum spanning forest.");
        }
        // Zero components only for an empty graph; otherwise exactly one tree.
        return forest.components().isEmpty() ? new MstResult(List.of(), 0L) : forest.components().get(0);
    }

    /**
     * Computes the minimum spanning forest of {@code graph}: a minimum spanning tree for
     * each connected component. Works for any graph, connected or not.
     *
     * @param graph an undirected, weighted graph
     * @return one {@link MstResult} per connected component
     * @throws IllegalArgumentException if {@code graph} is null
     */
    static MsfResult computeForest(Graph graph) {
        if (graph == null) {
            throw new IllegalArgumentException("Graph must not be null.");
        }
        int vertexCount = graph.vertexCount();
        boolean[] inTree = new boolean[vertexCount];
        List<MstResult> components = new ArrayList<>();

        // Vertices are visited in ascending order, so each unvisited vertex starts the
        // next component and components come out ordered by their lowest vertex index.
        for (int vertex = 0; vertex < vertexCount; vertex++) {
            if (!inTree[vertex]) {
                components.add(growComponent(graph, inTree, vertex));
            }
        }
        return new MsfResult(components);
    }

    /**
     * Grows a single minimum spanning tree from {@code start} over the vertices reachable
     * from it, marking each visited vertex in {@code inTree}. The frontier empties exactly
     * when the component is fully spanned.
     */
    private static MstResult growComponent(Graph graph, boolean[] inTree, int start) {
        List<Edge> edges = new ArrayList<>();
        long totalWeight = 0L;

        // Min-heap of candidate crossing edges, ordered by weight.
        PriorityQueue<Edge> frontier = new PriorityQueue<>(Comparator.comparingInt(Edge::weight));
        expandFrom(graph, inTree, start, frontier);

        while (!frontier.isEmpty()) {
            Edge cheapest = frontier.poll();
            if (inTree[cheapest.to()]) {
                continue; // Stale entry: the endpoint was already connected.
            }
            edges.add(cheapest);
            totalWeight += cheapest.weight();
            expandFrom(graph, inTree, cheapest.to(), frontier);
        }
        return new MstResult(edges, totalWeight);
    }

    /**
     * Marks {@code vertex} as part of the tree and pushes every edge leading from it to
     * a vertex not yet in the tree onto the frontier.
     */
    private static void expandFrom(Graph graph, boolean[] inTree, int vertex, PriorityQueue<Edge> frontier) {
        inTree[vertex] = true;
        for (Graph.Neighbor neighbor : graph.neighbors(vertex)) {
            if (!inTree[neighbor.vertex()]) {
                frontier.add(new Edge(vertex, neighbor.vertex(), neighbor.weight()));
            }
        }
    }

    /** Renders an MST result as a human-readable edge/weight table. */
    static String format(MstResult result) {
        StringBuilder sb = new StringBuilder("Edge \tWeight");
        for (Edge edge : result.edges()) {
            sb.append('\n').append(edge.from()).append(" - ").append(edge.to())
              .append('\t').append(edge.weight());
        }
        sb.append("\nTotal weight: ").append(result.totalWeight());
        return sb.toString();
    }

    /** Renders a minimum spanning forest as one labelled tree per component. */
    static String format(MsfResult forest) {
        StringBuilder sb = new StringBuilder("Minimum Spanning Forest (")
            .append(forest.componentCount()).append(" component(s))");
        int index = 1;
        for (MstResult component : forest.components()) {
            sb.append("\n\nComponent ").append(index++).append(":\n").append(format(component));
        }
        sb.append("\n\nForest total weight: ").append(forest.totalWeight());
        return sb.toString();
    }

    public static void main(String[] args) {
        int[][] connected = {
            { 0, 2, 0, 6, 0 },
            { 2, 0, 3, 8, 5 },
            { 0, 3, 0, 0, 7 },
            { 6, 8, 0, 0, 9 },
            { 0, 5, 7, 9, 0 },
        };
        System.out.println(format(compute(Graph.fromAdjacencyMatrix(connected))));

        // A disconnected graph: component {0,1,2}, component {3,4}, and isolated vertex 5.
        Graph disconnected = new Graph(6);
        disconnected.addEdge(0, 1, 1);
        disconnected.addEdge(1, 2, 2);
        disconnected.addEdge(0, 2, 5);
        disconnected.addEdge(3, 4, 4);
        System.out.println();
        System.out.println(format(computeForest(disconnected)));

        // Build a graph from an edge-list description (the same format accepted from a file).
        List<String> edgeList = List.of(
            "# from to weight",
            "vertices 4",
            "0 1 10",
            "1 2 20",
            "2 3 30",
            "0 3 40");
        System.out.println();
        System.out.println(format(compute(Graph.fromEdgeList(edgeList))));
    }
}

