         * Assembles a graph from any {@link GraphBuilder}. Each provided edge is validated
         * (endpoints in range, positive weight) as it is added.
         *
         * @throws IllegalArgumentException if {@code builder} is null or supplies an invalid edge
         */
        static Graph from(GraphBuilder builder) {
            if (builder == null) {
                throw new IllegalArgumentException("Graph builder must not be null.");
            }
            Graph graph = new Graph(builder.vertexCount());
            builder.provideEdges(graph::addEdge);
