     * Grows a single minimum spanning tree from {@code start} over the vertices reachable
     * from it, marking each visited vertex in {@code inTree}. The frontier empties exactly
     * when the component is fully spanned.
     */
    private static MstResult growComponent(Graph graph, boolean[] inTree, int start) {
        List<Edge> edges = new ArrayList<>();
        long totalWeight = 0L;

        // Min-heap of candidate crossing edges, ordered by weight.
        PriorityQueue<Edge> frontier = new PriorityQueue<>(Comparator.comparingInt(Edge::weight));
        expandFrom(graph, inTree, start, frontier);

        while (!frontier.isEmpty()) {
            Edge cheapest = frontier.poll();
            if (inTree[cheapest.to()]) {
                continue; // Stale entry: the endpoint was already connected.
            }
            edges.add(cheapest);
            totalWeight += cheapest.weight();
            expandFrom(graph, inTree, cheapest.to(), frontier);
        }
        return new MstResult(edges, totalWeight);
    }

    /**
     * Marks {@code vertex} as part of the tree and pushes every edge leading from it to
     * a vertex not yet in the tree onto the frontier.
     */
    private static void expandFrom(Graph graph, boolean[] inTree, int vertex, PriorityQueue<Edge> frontier) {
        inTree[vertex] = true;
        for (Graph.Neighbor neighbor : graph.neighbors(vertex)) {
            if (!inTree[neighbor.vertex()]) {
                frontier.add(new Edge(vertex, neighbor.vertex(), neighbor.weight()));
            }
        }
    }

    /** Renders an MST result as a human-readable edge/weight table. */
    static String format(MstResult result) {
        StringBuilder sb = new StringBuilder("Edge \tWeight");
        for (Edge edge : result.edges()) {
            sb.append('\n').append(edge.from()).append(" - ").append(edge.to())
              .append('\t').append(edge.weight());
        }
        sb.append("\nTotal weight: ").append(result.totalWeight());
        return sb.toString();
    }

    /** Renders a minimum spanning forest as one labelled tree per component. */
    static String format(MsfResult forest) {
        StringBuilder sb = new StringBuilder("Minimum Spanning Forest (")
            .append(forest.componentCount()).append(" component(s))");
        int index = 1;
        for (MstResult component : forest.components()) {
            sb.append("\n\nComponent ").append(index++).append(":\n").append(format(component));
        }
        sb.append("\n\nForest total weight: ").append(forest.totalWeight());
        return sb.toString();
    }

    public static void main(String[] args) {
        int[][] connected = {
            { 0, 2, 0, 6, 0 },
            { 2, 0, 3, 8, 5 },
            { 0, 3, 0, 0, 7 },
            { 6, 8, 0, 0, 9 },
            { 0, 5, 7, 9, 0 },
        };
        System.out.println(format(compute(Graph.fromAdjacencyMatrix(connected))));

        // A disconnected graph: component {0,1,2}, component {3,4}, and isolated vertex 5.
        Graph disconnected = new Graph(6);
        disconnected.addEdge(0, 1, 1);
        disconnected.addEdge(1, 2, 2);
        disconnected.addEdge(0, 2, 5);
        disconnected.addEdge(3, 4, 4);
        System.out.println();
        System.out.println(format(computeForest(disconnected)));

        // Build a graph from an edge-list description (the same format accepted from a file).
        List<String> edgeList = List.of(
            "# from to weight",
            "vertices 4",
            "0 1 10",
            "1 2 20",
            "2 3 30",
            "0 3 40");
        System.out.println();
        System.out.println(format(compute(Graph.fromEdgeList(edgeList))));
    }
}

