 * Computes a Minimum Spanning Tree (MST) — or, for a disconnected graph, a Minimum
 * Spanning Forest (MSF) — of an undirected, weighted graph using Prim's algorithm.
 *
 * <p>{@link #compute(Graph)} returns the MST of a connected graph and rejects a
 * disconnected one. {@link #computeForest(Graph)} is the general case: it grows one
 * minimum spanning tree per connected component and returns the collection, so it works
 * for any graph (isolated vertices become single-vertex, zero-edge components).
 *
 * <p>The algorithm operates on an adjacency-list {@link Graph}, so edge enumeration is
 * proportional to the number of edges rather than to {@code V^2}. Combined with a binary
 * heap to select the next cheapest crossing edge, the running time is {@code O(E log V)},
 * which is efficient for sparse graphs. A convenience adapter,
 * {@link Graph#fromAdjacencyMatrix(int[][])}, accepts the classic matrix form.
 */
public final class PrimsMst {

    private PrimsMst() {
        // Utility class: no instances.
    }

    /**
     * An edge of the minimum spanning tree, connecting {@code from} to {@code to}
     * with the given {@code weight}.
     */
    record Edge(int from, int to, int weight) {}

    /**
     * The result of a single-tree MST computation: the chosen edges and their total
     * weight. For a single-vertex component this holds no edges and zero weight.
     */
    record MstResult(List<Edge> edges, long totalWeight) {
        MstResult {
            edges = List.copyOf(edges);
        }
    }

    /**
     * The result of a Minimum Spanning Forest computation: one {@link MstResult} per
     * connected component, in ascending order of each component's lowest vertex index.
     */
    record MsfResult(List<MstResult> components) {
        MsfResult {
            components = List.copyOf(components);
        }

        /** The number of connected components (trees) in the forest. */
        int componentCount() {
            return components.size();
        }

        /** Every edge across all component trees. */
        List<Edge> edges() {
            return components.stream().flatMap(component -> component.edges().stream()).toList();
        }

        /** The combined weight of all component trees. */
        long totalWeight() {
            return components.stream().mapToLong(MstResult::totalWeight).sum();
        }
    }

    /**
