            () -> PrimsMst.Graph.fromEdgeList(null));
    }

    private static void edgeListFileRoundTrips() {
        Path file = null;
        try {
            file = Files.createTempFile("prims-edge-list", ".txt");
            Files.write(file, List.of("# sample", "vertices 5",
                "0 1 2", "0 3 6", "1 2 3", "1 3 8", "1 4 5", "2 4 7", "3 4 9"));
            PrimsMst.Graph g = PrimsMst.Graph.fromEdgeListFile(file);
            check("graph loaded from file yields MST weight 16", PrimsMst.compute(g).totalWeight() == 16);
        } catch (IOException e) {
