import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * Standalone, dependency-free tests for {@link PrimsMst}.
 *
 * <p>This repository compiles each algorithm as a plain {@code .java} file with no build
 * system, so these tests use a tiny built-in assertion harness rather than JUnit. Run:
 * <pre>{@code javac prims_mst.java PrimsMstTest.java && java PrimsMstTest}</pre>
 * The process exits with status 1 if any check fails, so it is usable from CI.
 */
public final class PrimsMstTest {

    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        knownMatrixMstHasExpectedWeightAndEdges();
        listBuildMatchesMatrixBuild();
        resultIsAValidSpanningTree();
        edgesAreReturnedInNonDecreasingWeightOrder();
        disconnectedGraphThrows();
        emptyGraphYieldsNoEdges();
        singleVertexYieldsNoEdges();
        nullGraphThrows();
        nonPositiveWeightThrows();
        nonSquareMatrixThrows();
        vertexOutOfRangeThrows();
        forestOfConnectedGraphIsSingleComponentEqualToMst();
        forestOfDisconnectedGraphHasPerComponentMsts();
        forestIncludesIsolatedVerticesAsEmptyComponents();
        forestOfEmptyGraphHasNoComponents();
        forestEdgeCountEqualsVerticesMinusComponents();
        forestNullGraphThrows();
        edgeListBuildMatchesMatrixBuild();
        edgeListIgnoresCommentsAndBlankLines();
        edgeListVerticesDirectiveAddsIsolatedVertices();
        edgeListMalformedLineThrows();
        edgeListNonIntegerTokenThrows();
        edgeListDeclaredCountTooSmallThrows();
        edgeListNullThrows();
        edgeListFileRoundTrips();
        graphFromCustomBuilder();
        computeAcceptsGraphBuilder();
        computeForestAcceptsGraphBuilder();
        edgeListGraphBuilderUsableAsInterface();
        nullBuilderThrows();

        System.out.printf("%n%d passed, %d failed%n", passed, failed);
        if (failed > 0) {
            System.exit(1);
        }
    }

    // --- The sample graph used across several tests; known MST weight is 16. ---

    private static int[][] sampleMatrix() {
        return new int[][] {
            { 0, 2, 0, 6, 0 },
            { 2, 0, 3, 8, 5 },
            { 0, 3, 0, 0, 7 },
            { 6, 8, 0, 0, 9 },
            { 0, 5, 7, 9, 0 },
        };
    }

    // --- Tests ---

    private static void knownMatrixMstHasExpectedWeightAndEdges() {
        PrimsMst.MstResult result = PrimsMst.compute(PrimsMst.Graph.fromAdjacencyMatrix(sampleMatrix()));
        check("known MST total weight is 16", result.totalWeight() == 16);
        // The MST of the sample graph is unique: {0-1:2, 1-2:3, 1-4:5, 0-3:6}.
        check("known MST has 4 edges", result.edges().size() == 4);
        check("known MST contains edge 0-1 (w=2)", hasEdge(result, 0, 1, 2));
        check("known MST contains edge 1-2 (w=3)", hasEdge(result, 1, 2, 3));
        check("known MST contains edge 1-4 (w=5)", hasEdge(result, 1, 4, 5));
        check("known MST contains edge 0-3 (w=6)", hasEdge(result, 0, 3, 6));
    }

    private static void listBuildMatchesMatrixBuild() {
        PrimsMst.Graph g = new PrimsMst.Graph(5);
        g.addEdge(0, 1, 2);
        g.addEdge(0, 3, 6);
        g.addEdge(1, 2, 3);
        g.addEdge(1, 3, 8);
        g.addEdge(1, 4, 5);
        g.addEdge(2, 4, 7);
        g.addEdge(3, 4, 9);
        long matrixWeight = PrimsMst.compute(PrimsMst.Graph.fromAdjacencyMatrix(sampleMatrix())).totalWeight();
        check("adjacency-list build matches matrix build", PrimsMst.compute(g).totalWeight() == matrixWeight);
    }

    private static void resultIsAValidSpanningTree() {
        PrimsMst.MstResult result = PrimsMst.compute(PrimsMst.Graph.fromAdjacencyMatrix(sampleMatrix()));
        int vertexCount = 5;
        check("spanning tree has V-1 edges", result.edges().size() == vertexCount - 1);

        // A spanning tree must connect every vertex and contain no cycle. With exactly
        // V-1 edges, "connects all vertices" already implies acyclicity, which we verify
        // via union-find: every union must merge two previously-distinct components.
        int[] parent = new int[vertexCount];
        for (int i = 0; i < vertexCount; i++) {
            parent[i] = i;
        }
        boolean acyclic = true;
        for (PrimsMst.Edge e : result.edges()) {
            if (!union(parent, e.from(), e.to())) {
                acyclic = false;
            }
        }
        check("spanning tree is acyclic", acyclic);

        int root = find(parent, 0);
        boolean connected = true;
        for (int v = 1; v < vertexCount; v++) {
            connected &= find(parent, v) == root;
        }
        check("spanning tree connects all vertices", connected);
    }

    private static void edgesAreReturnedInNonDecreasingWeightOrder() {
        // Prim's pulls crossing edges from a min-heap, so emitted weights never decrease.
        PrimsMst.MstResult result = PrimsMst.compute(PrimsMst.Graph.fromAdjacencyMatrix(sampleMatrix()));
        boolean ordered = true;
        int previous = Integer.MIN_VALUE;
        for (PrimsMst.Edge e : result.edges()) {
            ordered &= e.weight() >= previous;
            previous = e.weight();
        }
        check("MST edges are emitted in non-decreasing weight order", ordered);
    }

    private static void disconnectedGraphThrows() {
        PrimsMst.Graph g = new PrimsMst.Graph(3);
        g.addEdge(0, 1, 1); // vertex 2 is isolated
        expectThrows("disconnected graph throws", IllegalArgumentException.class,
            () -> PrimsMst.compute(g));
    }

    private static void emptyGraphYieldsNoEdges() {
        PrimsMst.MstResult result = PrimsMst.compute(new PrimsMst.Graph(0));
        check("empty graph has no edges", result.edges().isEmpty());
        check("empty graph has zero weight", result.totalWeight() == 0L);
    }

    private static void singleVertexYieldsNoEdges() {
        PrimsMst.MstResult result = PrimsMst.compute(new PrimsMst.Graph(1));
        check("single-vertex graph has no edges", result.edges().isEmpty());
        check("single-vertex graph has zero weight", result.totalWeight() == 0L);
    }

    private static void nullGraphThrows() {
        expectThrows("null graph throws", IllegalArgumentException.class,
            () -> PrimsMst.compute(null));
    }

    private static void nonPositiveWeightThrows() {
        expectThrows("zero/negative edge weight throws", IllegalArgumentException.class,
            () -> new PrimsMst.Graph(2).addEdge(0, 1, 0));
    }

    private static void nonSquareMatrixThrows() {
        int[][] ragged = { { 0, 1 }, { 1 } };
        expectThrows("non-square matrix throws", IllegalArgumentException.class,
            () -> PrimsMst.Graph.fromAdjacencyMatrix(ragged));
    }

    private static void vertexOutOfRangeThrows() {
        expectThrows("out-of-range vertex throws", IndexOutOfBoundsException.class,
            () -> new PrimsMst.Graph(2).addEdge(0, 5, 1));
    }

    // --- Minimum Spanning Forest ---

    /** A disconnected graph: component {0,1,2} (MST weight 3), {3,4} (weight 4), isolated 5. */
    private static PrimsMst.Graph disconnectedGraph() {
        PrimsMst.Graph g = new PrimsMst.Graph(6);
        g.addEdge(0, 1, 1);
        g.addEdge(1, 2, 2);
        g.addEdge(0, 2, 5); // redundant heavier edge within the first component
        g.addEdge(3, 4, 4);
        return g;
    }

    private static void forestOfConnectedGraphIsSingleComponentEqualToMst() {
        PrimsMst.MsfResult forest = PrimsMst.computeForest(PrimsMst.Graph.fromAdjacencyMatrix(sampleMatrix()));
        check("forest of connected graph has one component", forest.componentCount() == 1);
        check("forest of connected graph matches MST weight", forest.totalWeight() == 16);
    }

    private static void forestOfDisconnectedGraphHasPerComponentMsts() {
        PrimsMst.MsfResult forest = PrimsMst.computeForest(disconnectedGraph());
        check("disconnected graph yields 3 components", forest.componentCount() == 3);
        // Components are ordered by lowest vertex index: {0,1,2}, {3,4}, {5}.
        check("first component MST weight is 3", forest.components().get(0).totalWeight() == 3);
        check("second component MST weight is 4", forest.components().get(1).totalWeight() == 4);
        check("third component (isolated) MST weight is 0", forest.components().get(2).totalWeight() == 0);
        check("forest total weight is 7", forest.totalWeight() == 7);
    }

    private static void forestIncludesIsolatedVerticesAsEmptyComponents() {
        PrimsMst.MsfResult forest = PrimsMst.computeForest(disconnectedGraph());
        check("isolated vertex is an edgeless component", forest.components().get(2).edges().isEmpty());
    }

    private static void forestOfEmptyGraphHasNoComponents() {
        PrimsMst.MsfResult forest = PrimsMst.computeForest(new PrimsMst.Graph(0));
        check("empty graph forest has no components", forest.componentCount() == 0);
        check("empty graph forest has zero weight", forest.totalWeight() == 0L);
        check("empty graph forest has no edges", forest.edges().isEmpty());
    }

    private static void forestEdgeCountEqualsVerticesMinusComponents() {
        // A spanning forest of V vertices with C components always has exactly V - C edges.
        PrimsMst.MsfResult forest = PrimsMst.computeForest(disconnectedGraph());
        int vertices = 6;
        check("forest has V - C edges", forest.edges().size() == vertices - forest.componentCount());
    }

    private static void forestNullGraphThrows() {
        expectThrows("null graph forest throws", IllegalArgumentException.class,
            () -> PrimsMst.computeForest(null));
    }

    // --- Edge-list loading ---

    private static void edgeListBuildMatchesMatrixBuild() {
        // The sample graph expressed as an edge list (upper triangle of its matrix).
        List<String> lines = List.of(
            "vertices 5",
            "0 1 2", "0 3 6", "1 2 3", "1 3 8", "1 4 5", "2 4 7", "3 4 9");
        PrimsMst.Graph g = PrimsMst.Graph.fromEdgeList(lines);
        check("edge-list build matches matrix build", PrimsMst.compute(g).totalWeight() == 16);
    }

    private static void edgeListIgnoresCommentsAndBlankLines() {
        List<String> lines = List.of(
            "# a triangle",
            "",
            "0 1 5   # cheapest from 0",
            "   ",
            "1 2 7",
            "0 2 9");
        PrimsMst.MstResult result = PrimsMst.compute(PrimsMst.Graph.fromEdgeList(lines));
        check("comments/blank lines ignored; MST weight is 12", result.totalWeight() == 12);
        check("inferred vertex count yields 2 MST edges", result.edges().size() == 2);
    }

    private static void edgeListVerticesDirectiveAddsIsolatedVertices() {
        // Four vertices declared but vertex 3 appears in no edge -> a separate component.
        List<String> lines = List.of("vertices 4", "0 1 1", "1 2 2");
        PrimsMst.MsfResult forest = PrimsMst.computeForest(PrimsMst.Graph.fromEdgeList(lines));
        check("declared isolated vertex becomes its own component", forest.componentCount() == 2);
        check("forest weight ignores the isolated vertex", forest.totalWeight() == 3);
    }

    private static void edgeListMalformedLineThrows() {
        expectThrows("edge line with too few tokens throws", IllegalArgumentException.class,
            () -> PrimsMst.Graph.fromEdgeList(List.of("0 1")));
    }

    private static void edgeListNonIntegerTokenThrows() {
        expectThrows("non-integer token throws", IllegalArgumentException.class,
            () -> PrimsMst.Graph.fromEdgeList(List.of("a b c")));
    }

    private static void edgeListDeclaredCountTooSmallThrows() {
        expectThrows("declared count smaller than referenced index throws", IllegalArgumentException.class,
            () -> PrimsMst.Graph.fromEdgeList(List.of("vertices 1", "0 2 5")));
    }

    private static void edgeListNullThrows() {
        expectThrows("null edge list throws", IllegalArgumentException.class,
            () -> PrimsMst.Graph.fromEdgeList(null));
    }

    private static void edgeListFileRoundTrips() {
        Path file = null;
        try {
            file = Files.createTempFile("prims-edge-list", ".txt");
            Files.write(file, List.of("# sample", "vertices 5",
                "0 1 2", "0 3 6", "1 2 3", "1 3 8", "1 4 5", "2 4 7", "3 4 9"));
            PrimsMst.Graph g = PrimsMst.Graph.fromEdgeListFile(file);
            check("graph loaded from file yields MST weight 16", PrimsMst.compute(g).totalWeight() == 16);
        } catch (IOException e) {
            check("edge-list file round-trip (I/O failed: " + e.getMessage() + ")", false);
        } finally {
            if (file != null) {
                try {
                    Files.deleteIfExists(file);
                } catch (IOException ignored) {
                    // Temp file cleanup is best-effort.
                }
            }
        }
    }

    // --- GraphBuilder abstraction ---

    /** A custom edge provider: a triangle 0-1-2 with weights 1, 2, 3 (MST weight 3). */
    private static PrimsMst.GraphBuilder triangleBuilder() {
        return new PrimsMst.GraphBuilder() {
            @Override public int vertexCount() {
                return 3;
            }
            @Override public void provideEdges(EdgeSink sink) {
                sink.accept(0, 1, 1);
                sink.accept(1, 2, 2);
                sink.accept(0, 2, 3);
            }
        };
    }

    private static void graphFromCustomBuilder() {
        PrimsMst.Graph g = PrimsMst.Graph.from(triangleBuilder());
        check("Graph.from(custom builder) yields MST weight 3", PrimsMst.compute(g).totalWeight() == 3);
    }

    private static void computeAcceptsGraphBuilder() {
        check("compute(GraphBuilder) yields MST weight 3", PrimsMst.compute(triangleBuilder()).totalWeight() == 3);
    }

    private static void computeForestAcceptsGraphBuilder() {
        // A custom provider describing two disjoint edges over four vertices -> two components.
        PrimsMst.GraphBuilder twoComponents = new PrimsMst.GraphBuilder() {
            @Override public int vertexCount() {
                return 4;
            }
            @Override public void provideEdges(EdgeSink sink) {
                sink.accept(0, 1, 5);
                sink.accept(2, 3, 7);
            }
        };
        PrimsMst.MsfResult forest = PrimsMst.computeForest(twoComponents);
        check("computeForest(GraphBuilder) finds 2 components", forest.componentCount() == 2);
        check("computeForest(GraphBuilder) total weight is 12", forest.totalWeight() == 12);
    }

    private static void edgeListGraphBuilderUsableAsInterface() {
        PrimsMst.GraphBuilder builder = new PrimsMst.EdgeListGraphBuilder(List.of("0 1 4", "1 2 6"));
        check("EdgeListGraphBuilder is a GraphBuilder usable via Graph.from",
            PrimsMst.compute(PrimsMst.Graph.from(builder)).totalWeight() == 10);
    }

    private static void nullBuilderThrows() {
        expectThrows("Graph.from(null) throws", IllegalArgumentException.class,
            () -> PrimsMst.Graph.from(null));
    }

    // --- Assertion harness ---

    private static void check(String name, boolean condition) {
        if (condition) {
            passed++;
            System.out.println("  PASS: " + name);
        } else {
            failed++;
            System.out.println("  FAIL: " + name);
        }
    }

    private static void expectThrows(String name, Class<? extends Throwable> expected, Runnable action) {
        try {
            action.run();
            failed++;
            System.out.println("  FAIL: " + name + " (no exception thrown)");
        } catch (Throwable thrown) {
            boolean ok = expected.isInstance(thrown);
            check(name + (ok ? "" : " (got " + thrown.getClass().getSimpleName() + ")"), ok);
        }
    }

    // --- Helpers ---

    private static boolean hasEdge(PrimsMst.MstResult result, int a, int b, int weight) {
        for (PrimsMst.Edge e : result.edges()) {
            boolean sameEndpoints = (e.from() == a && e.to() == b) || (e.from() == b && e.to() == a);
            if (sameEndpoints && e.weight() == weight) {
                return true;
            }
        }
        return false;
    }

    private static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    /** Unions the sets of {@code a} and {@code b}; returns false if they were already joined. */
    private static boolean union(int[] parent, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra == rb) {
            return false;
        }
        parent[ra] = rb;
        return true;
    }

    private PrimsMstTest() {
        // Test entry point only.
    }
}
